internal sealed class AlgebraicHeisenbergFockDocument : IScribeDocumentDefinition
{
    private static DocumentBlock D(string selector, string text) => Describe.Lean(
        DescribeId.Create("algebraicheisenbergfock-" + selector.Replace('.', '-').Replace('_', '-').ToLowerInvariant()),
        DeclarationHandle.Create("D5/S3/Quantum/Algebra/AlgebraicHeisenbergFock." + selector),
